<?php session_name('VS_CUSTOMER');session_start();if(!isset($_SESSION['user_id'])||($_SESSION['user_role']??'')!=='user'){header('Location: login.php');exit;}require_once 'includes/header.php';?>
<section class="page-shell" id="fleet"><div class="section-head"><div><span class="eyebrow dark">OUR FLEET</span><h1>Choose your next ride</h1><p class="muted">Search the fleet, review vehicle details and see your rental total before requesting.</p></div></div><div class="filter-bar"><input id="search" placeholder="Search vehicle name"><select id="type"><option value="">All types</option><option>Car</option><option>Bike</option></select><select id="status"><option value="">All status</option><option>Available</option><option>Booked</option><option>On Rent</option><option>Maintenance</option></select><button class="btn" onclick="loadVehicles()">Search fleet</button></div><div id="vehicles" class="vehicle-grid"><div class="empty-card">Loading vehicles…</div></div></section>
<script>
let fleet=[];const fallback=v=>v.type==='Bike'?'https://images.unsplash.com/photo-1558981806-ec527fa84c39?auto=format&fit=crop&w=900&q=80':'https://images.unsplash.com/photo-1492144534655-ae79c964c9d7?auto=format&fit=crop&w=900&q=80';
function calc(id){const v=fleet.find(x=>x.id===id),s=document.getElementById('s-'+id).value,e=document.getElementById('e-'+id).value,out=document.getElementById('sum-'+id);if(!s||!e){out.textContent='Select dates to see total';return}const a=new Date(s+'T00:00:00'),b=new Date(e+'T00:00:00');if(b<a){out.textContent='Return date must be after pickup date';return}const days=Math.round((b-a)/86400000)+1;out.innerHTML=`${days} day${days>1?'s':''} × ₹${Number(v.pricePerDay).toLocaleString('en-IN')} = <strong>₹${Number(days*v.pricePerDay).toLocaleString('en-IN')}</strong>`}
async function loadVehicles(){try{const j=await (await fetch('api/vehicles/')).json();fleet=j.data||[];const q=document.getElementById('search').value.toLowerCase().trim(),t=document.getElementById('type').value,s=document.getElementById('status').value;const list=fleet.filter(v=>(!q||v.name.toLowerCase().includes(q))&&(!t||v.type===t)&&(!s||v.status===s));vehicles.innerHTML=list.length?list.map(v=>`<article class="vehicle-card"><div class="vehicle-photo" style="background-image:url('${v.image||fallback(v)}')"><span class="status ${v.status==='Available'?'ok':'off'}">${v.status}</span></div><div class="vehicle-body"><div class="vehicle-title"><div><small>${v.type}${v.registrationNumber?' • '+v.registrationNumber:''}</small><h3>${v.name}</h3></div><div class="price">₹${Number(v.pricePerDay).toLocaleString('en-IN')}<small>/day</small></div></div><div class="spec-grid"><span>👥 ${v.seats} seats</span><span>⛽ ${v.fuel}</span><span>⚙ ${v.transmission}</span></div><p class="muted">${v.description||''}</p>${v.status==='Maintenance'?'<button class="btn wide disabled" disabled>Under maintenance</button>':`<div class="booking-row"><label>Pickup date<input type="date" id="s-${v.id}" onchange="calc('${v.id}')"></label><label>Return date<input type="date" id="e-${v.id}" onchange="calc('${v.id}')"></label></div><div class="booking-extra"><input id="pl-${v.id}" placeholder="Pickup location"><input id="rl-${v.id}" placeholder="Return location"></div><div class="price-preview" id="sum-${v.id}">Select dates to see total</div><button class="btn wide" onclick="requestBooking('${v.id}')">Request booking</button>`}</div></article>`).join(''):'<div class="empty-card">No vehicles match your filters.</div>'}catch(e){vehicles.innerHTML='<div class="empty-card">Unable to load vehicles.</div>'}}
async function requestBooking(id){const startDate=document.getElementById('s-'+id).value,endDate=document.getElementById('e-'+id).value,pickupLocation=document.getElementById('pl-'+id).value.trim(),returnLocation=document.getElementById('rl-'+id).value.trim();if(!startDate||!endDate||!pickupLocation||!returnLocation){toast('Please select dates and enter pickup and return locations.','error');return}const j=await (await fetch('api/bookings/create.php',{method:'POST',headers:{'Content-Type':'application/json'},credentials:'include',body:JSON.stringify({vehicleId:id,startDate,endDate,pickupLocation,returnLocation})})).json();toast(j.message,j.success?'success':'error');if(j.success)setTimeout(()=>location.href='bookings.php',700)}loadVehicles();
</script><?php require_once 'includes/footer.php';?>
